import java.util.HashMap;
import java.util.Map;

class Solution {
    public String minWindow(String s, String t) {
        if (s.length() < t.length()) return "";
        Map<Character, Integer> target = new HashMap<>();
        for (char c : t.toCharArray()) target.put(c, target.getOrDefault(c, 0) + 1);

        Map<Character, Integer> window = new HashMap<>();
        int have = 0, need = target.size();
        int[] res = {-1, -1};
        int minLen = Integer.MAX_VALUE, left = 0;

        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            window.put(c, window.getOrDefault(c, 0) + 1);
            if (target.containsKey(c) && window.get(c).intValue() == target.get(c).intValue()) have++;

            while (have == need) {
                if (right - left + 1 < minLen) {
                    minLen = right - left + 1;
                    res[0] = left;
                    res[1] = right;
                }
                char leftChar = s.charAt(left++);
                window.put(leftChar, window.get(leftChar) - 1);
                if (target.containsKey(leftChar) && window.get(leftChar) < target.get(leftChar)) have--;
            }
        }
        return res[0] == -1 ? "" : s.substring(res[0], res[1] + 1);
    }
}

