function minWindow(s: string, t: string): string {
  if (s.length < t.length) return '';
  const target = new Map<string, number>();
  for (const c of t) target.set(c, (target.get(c) || 0) + 1);

  const window = new Map<string, number>();
  let have = 0, need = target.size;
  let res = [-1, -1], minLen = Infinity, left = 0;

  for (let right = 0; right < s.length; right++) {
    const c = s[right];
    window.set(c, (window.get(c) || 0) + 1);
    if (target.has(c) && window.get(c) === target.get(c)) have++;

    while (have === need) {
      if (right - left + 1 < minLen) {
        minLen = right - left + 1;
        res = [left, right];
      }
      const lc = s[left++];
      window.set(lc, window.get(lc)! - 1);
      if (target.has(lc) && window.get(lc)! < target.get(lc)!) have--;
    }
  }
  return res[0] === -1 ? '' : s.slice(res[0], res[1] + 1);
}

